import datetime
import math
import re
import polars as pl

NULL_VALUES = {"", "N/A", "n/a", "-", "null"}


def _clean_str(col: pl.Expr) -> pl.Expr:
    return pl.when(col.is_in(list(NULL_VALUES))).then(None).otherwise(col)


def transform(raw: pl.DataFrame) -> pl.DataFrame:
    return raw.select(
        contact_id=_clean_str(pl.col("Customer ID")).str.to_uppercase(),
        full_name=_clean_str(pl.col("Customer Name")),
        email=_clean_str(pl.col("Email Address")).str.to_lowercase(),
        phone=_clean_str(pl.col("Telephone")),
        company=_clean_str(pl.col("Company")),
        created_on=_clean_str(pl.col("Signup Date")).str.to_date(
            format="%Y-%m-%d", strict=False
        ),
        lifetime_value=_clean_str(pl.col("LTV"))
        .cast(pl.Float64, strict=False)
        .round(2),
    )
